CREATE TEMPORARY VIEW dwd_fp_search_location_type_${grass_region_without_quote} AS
SELECT
    user_id
    ,request_id
    ,item_id
    ,IF(sort_type IS NULL, 'NA', sort_type) AS sort_type
    ,CASE 
        WHEN location <20 THEN '20 below'
        WHEN location >= 20 AND location < 40 THEN '20-40'
    END AS location_type
    ,IF(card_type IS NULL, 'NA', card_type) AS card_type
    ,CASE WHEN sub_product_type IS NOT NULL THEN sub_product_type
        WHEN is_ads IS NOT TRUE THEN 'Non Ads'
        ELSE 'others'
    END AS ads_type
    
    ,MAX(rel_raw) AS rel_raw
    ,MAX(rel_lx) AS rel_lx
    ,MAX(rel_add) AS rel_add
FROM srdi_mart.dwd_fp_search_base_1d
WHERE country IN (${grass_region})
    AND dt = ${local_date}
    AND location <= 39
    AND imp_time IS NOT NULL
    AND user_id > 0
    AND rel_raw != 0 
    AND rel_lx IS NOT NULL
GROUP BY 
    1,2,3,4,5,6,7;

