CREATE TEMPORARY VIEW dwd_fp_search_search_mid_${grass_region_without_quote} AS
SELECT
    user_id
    ,request_id
    ,item_id
    ,IF(search_mid LIKE 'image%', array(search_mid, '__ALL__', 'mutimodel_search_all'), array(search_mid, '__ALL__', 'text_search_all')) AS search_mids
    ,ARRAY(IF(COALESCE(keyword, '') = '', 'false', 'true'), '__ALL__') AS with_keywords
    ,CASE 
        WHEN location <= 3 THEN ARRAY('0-3', '0-19', '0-39')
        WHEN location < 20 THEN ARRAY('0-19', '0-39') 
        WHEN location < 40 THEN ARRAY('0-39', '20-39')
    END AS location_types
    
    ,MAX(rel_raw) AS rel_raw
    ,MAX(rel_lx) AS rel_lx
    ,MAX(rel_add) AS rel_add
FROM srdi_mart.dwd_fp_search_base_1d
WHERE country IN (${grass_region})
    AND dt = ${local_date}
    AND location <= 39
    AND imp_time IS NOT NULL
    AND user_id > 0
    AND rel_raw != 0 
    AND rel_lx IS NOT NULL
GROUP BY 
    1,2,3,4,5,6;

