CREATE TEMPORARY VIEW dwd_fp_search_search_location_explode_${grass_region_without_quote} AS
SELECT
    user_id
    ,request_id
    ,item_id
    ,search_mid
    ,with_keyword
    ,location_type
    
    ,MAX(rel_raw) AS rel_raw
    ,MAX(rel_lx) AS rel_lx
    ,MAX(rel_add) AS rel_add
FROM dwd_fp_search_search_mid_${grass_region_without_quote}
    LATERAL VIEW EXPLODE(location_types) AS location_type
    LATERAL VIEW EXPLODE(search_mids) AS search_mid
    LATERAL VIEW EXPLODE(with_keywords) AS with_keyword
GROUP BY 
    1,2,3,4,5,6;

