CREATE TEMPORARY VIEW search_rel_metrics_by_req_${grass_region_without_quote} AS
SELECT 
    user_id
    ,request_id
    ,location_type
    ,IF(ads_type IS NOT NULL, ads_type, '__ALL__') AS ads_type
    ,IF(sort_type IS NOT NULL, sort_type, '__ALL__') AS sort_type
    ,IF(card_type IS NOT NULL, card_type, '__ALL__') AS card_type
    ,'__ALL__' AS search_mid
    ,'__ALL__' AS with_keyword

    ,SUM(rel_raw) AS total_rel_score
    ,SUM(CASE WHEN rel_add >=0 THEN rel_add ELSE 0 END) AS total_rel_add
    ,COUNT(1) AS item_imp_cnt
    ,SUM(CASE WHEN rel_lx = 0 AND rel_raw > 0 THEN 1 ELSE 0 END) AS irrelevant_cnt
    ,SUM(CASE WHEN rel_lx = 1 THEN 1 ELSE 0 END) AS somewhat_cnt
    ,SUM(CASE WHEN rel_lx = 0 AND rel_raw > 0 THEN 4 WHEN rel_lx = 1 THEN 0.5 ELSE NULL END) AS bad_case_cnt
    ,SUM(CASE WHEN rel_lx = 3 THEN 1 ELSE 0 END) AS same_cnt
    ,AVG(1.0 * rel_raw) AS request_avg_rel_raw
    ,AVG(1.0 * CASE WHEN rel_add >=0 THEN rel_add ELSE 0 END ) AS request_avg_rel_add
    
FROM dwd_fp_search_location_type_${grass_region_without_quote}
    GROUP BY GROUPING SETS
(
    -- Base dimension user_id, request_id, location_type. Cube dimension ads_type, sort_type, card_type
    (user_id, request_id, location_type, ads_type, sort_type, card_type), (user_id, request_id, location_type, ads_type, sort_type)
    ,(user_id, request_id, location_type, ads_type, card_type), (user_id, request_id, location_type, ads_type)
    ,(user_id, request_id, location_type, sort_type, card_type), (user_id, request_id, location_type, sort_type)
    ,(user_id, request_id, location_type, card_type), (user_id, request_id, location_type)
)
UNION ALL 
SELECT 
    user_id
    ,request_id
    ,'__ALL__' AS location_type
    ,IF(ads_type IS NOT NULL, ads_type, '__ALL__') AS ads_type
    ,IF(sort_type IS NOT NULL, sort_type, '__ALL__') AS sort_type
    ,IF(card_type IS NOT NULL, card_type, '__ALL__') AS card_type
    ,'__ALL__' AS search_mid
    ,'__ALL__' AS with_keyword

    ,SUM(rel_raw) AS total_rel_score
    ,SUM(CASE WHEN rel_add >=0 THEN rel_add ELSE 0 END) AS total_rel_add
    ,COUNT(1) AS item_imp_cnt
    ,SUM(CASE WHEN rel_lx = 0 AND rel_raw > 0 THEN 1 ELSE 0 END) AS irrelevant_cnt
    ,SUM(CASE WHEN rel_lx = 1 THEN 1 ELSE 0 END) AS somewhat_cnt
    ,SUM(CASE WHEN rel_lx = 0 AND rel_raw > 0 THEN 4 WHEN rel_lx = 1 THEN 0.5 ELSE NULL END) AS bad_case_cnt
    ,SUM(CASE WHEN rel_lx = 3 THEN 1 ELSE 0 END) AS same_cnt
    ,AVG(1.0 * rel_raw) AS request_avg_rel_raw
    ,AVG(1.0 * CASE WHEN rel_add >=0 THEN rel_add ELSE 0 END ) AS request_avg_rel_add
    
FROM dwd_fp_search_${grass_region_without_quote}
    GROUP BY GROUPING SETS
(
    -- Base dimension user_id, request_id. Cube dimension ads_type, sort_type, card_type
    (user_id, request_id, ads_type, sort_type, card_type), (user_id, request_id, ads_type, sort_type)
    ,(user_id, request_id, ads_type, card_type), (user_id, request_id, ads_type)
    ,(user_id, request_id, sort_type, card_type), (user_id, request_id, sort_type)
    ,(user_id, request_id, card_type), (user_id, request_id)
)
UNION ALL 
SELECT 
    user_id
    ,request_id
    ,location_type
    ,'__ALL__' AS ads_type
    ,'__ALL__' AS sort_type
    ,'__ALL__' AS card_type
    ,search_mid
    ,with_keyword

    ,SUM(rel_raw) AS total_rel_score
    ,SUM(CASE WHEN rel_add >=0 THEN rel_add ELSE 0 END) AS total_rel_add
    ,COUNT(1) AS item_imp_cnt
    ,SUM(CASE WHEN rel_lx = 0 AND rel_raw > 0 THEN 1 ELSE 0 END) AS irrelevant_cnt
    ,SUM(CASE WHEN rel_lx = 1 THEN 1 ELSE 0 END) AS somewhat_cnt
    ,SUM(CASE WHEN rel_lx = 0 AND rel_raw > 0 THEN 4 WHEN rel_lx = 1 THEN 0.5 ELSE NULL END) AS bad_case_cnt
    ,SUM(CASE WHEN rel_lx = 3 THEN 1 ELSE 0 END) AS same_cnt
    ,AVG(1.0 * rel_raw) AS request_avg_rel_raw
    ,AVG(1.0 * CASE WHEN rel_add >=0 THEN rel_add ELSE 0 END ) AS request_avg_rel_add
    
FROM 
    dwd_fp_search_search_location_explode_${grass_region_without_quote}
GROUP BY 
    1,2,3,7,8;

