CREATE TEMPORARY VIEW search_rel_metrics_by_user_${grass_region_without_quote} AS
SELECT 
    user_id
    ,location_type
    ,ads_type
    ,sort_type
    ,card_type
    ,search_mid
    ,with_keyword

    ,SUM(total_rel_score) AS total_rel_score
    ,SUM(total_rel_add) AS total_rel_add
    ,SUM(item_imp_cnt) AS imp_item_num
    ,SUM(irrelevant_cnt) AS irrelevant_cnt
    ,SUM(somewhat_cnt) AS somewhat_cnt
    ,SUM(bad_case_cnt) AS bad_case_cnt
    ,SUM(same_cnt) AS same_cnt
    ,COUNT(1) AS request_cnt
    ,COUNT(CASE WHEN 1.0 * bad_case_cnt / item_imp_cnt > 0.2 THEN 1 ELSE NULL END) AS bad_query_cnt
    ,COUNT(CASE WHEN irrelevant_cnt = 0 AND somewhat_cnt <= 1 AND same_cnt >= 1
        THEN 1 ELSE NULL END) AS good_query_cnt
    
    ,SUM(request_avg_rel_raw) AS request_avg_rel_raw
    ,SUM(request_avg_rel_add) AS request_avg_rel_add
FROM 
    search_rel_metrics_by_req_${grass_region_without_quote}
GROUP BY 1,2,3,4,5,6,7;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_card_type_relevance_metrics_1d
PARTITION (
    grass_region=${grass_region},
    local_date=${local_date}
)
SELECT 
/*+ REPARTITION(10) */
    exp_group_id
    ,ads_type
    ,sort_type
    ,location_type AS top_location_type
    ,card_type
    

    ,SUM(imp_item_num) AS imp_item_num
    ,SUM(request_cnt) AS request_cnt
    ,SUM(total_rel_score) AS total_rel_score
    ,SUM(request_avg_rel_raw) AS request_avg_rel_raw
    ,SUM(total_rel_add) AS total_rel_add
    ,SUM(request_avg_rel_add) AS request_avg_rel_add

    ,SUM(bad_query_cnt) AS bad_query_cnt
    ,SUM(bad_case_cnt) AS bad_case_cnt
    ,SUM(irrelevant_cnt) AS irrelevant_cnt
    ,SUM(somewhat_cnt) AS somewhat_cnt
    ,search_mid
    ,with_keyword

    ,SUM(same_cnt) AS same_cnt
    ,SUM(good_query_cnt) AS good_query_cnt
FROM 
    search_rel_metrics_by_user_${grass_region_without_quote} a
    INNER JOIN user_exp_mapping_${grass_region_without_quote} b
        ON a.user_id = b.user_id
GROUP BY
    exp_group_id
    ,ads_type
    ,sort_type
    ,location_type
    ,card_type
    ,search_mid
    ,with_keyword
